#include <stdio.h>
#include <stdlib.h>

int main() {
    int *ptr = malloc(sizeof(int));
    if (ptr == NULL) {
        printf("Allocation failed\n");
        return 1;
    }
    *ptr = 42;
    printf("%d\n", *ptr);
    free(ptr);
    return 0;
}
